import { MigrateUpArgs, MigrateDownArgs, sql } from '@payloadcms/db-postgres'

/*
 * #2829 W2 — pages become a tree; navigation, footer and settings grow.
 *
 * 1. SCHEMA (generated by `payload migrate:create` against the W1 schema,
 *    then the W1 statements already shipped in 20261025_100000 removed):
 *    pages gain parent / kind / collection / planned_offering / seo image /
 *    seo noindex; navigation gains items (+ dropdown children), a header
 *    button and a wordmark; footer gains tagline lines, location, email,
 *    columns, socials, copyright, built-by; site settings gain collection
 *    base paths, language, timezone and redirects. Every new column is
 *    nullable or defaulted, so no row is rewritten to add them.
 * 2. DATA (customer content preserved, in BOTH the live rows and the version
 *    rows Studio actually reads — every Studio read is a draft read, so the
 *    latest version row is the truth):
 *    - each page's address comes from its old role: home → '' (the home page),
 *      every other role → the slug it already had (about, menu, gallery,
 *      contact, reservations). Every converted page is top level, kind
 *      'standard', so every published URL keeps working.
 *    - the header menu is rebuilt from what visitors were actually shown:
 *      the enabled pages in their old menu order, labelled with their old menu
 *      label. (The old navigation page list was stored but never rendered.)
 * 3. DESTRUCTIVE, LAST: the role / menu-label / menu-order columns, the role
 *    enums and the old navigation page relationship are dropped only after
 *    step 2 has copied what they held.
 *
 * Runs in one transaction (Payload wraps each migration). NOT APPLIED BY THE
 * AUTHOR to any non-local database.
 */

